// Enhanced Input Validator with proper error handling
const input = $input.first().json;

console.log('=== ROUTE PLANNING INPUT VALIDATION ===');
console.log('Raw input:', JSON.stringify(input, null, 2));

// Helper function for ISK formatting - MOVE TO TOP
function formatISK(value) {
  if (!value || value === 0) return '0 ISK';
  if (value >= 1000000000000) return `${(value / 1000000000000).toFixed(1)}T ISK`;
  if (value >= 1000000000) return `${(value / 1000000000).toFixed(1)}B ISK`;
  if (value >= 1000000) return `${(value / 1000000).toFixed(0)}M ISK`;
  if (value >= 1000) return `${(value / 1000).toFixed(0)}K ISK`;
  return `${Math.round(value).toLocaleString()} ISK`;
}

try {
  // Extract and validate inputs with proper defaults
  const origin = input.origin?.toString().trim();
  const destination = input.destination?.toString().trim();
  const routePreference = input.route_preference?.toString().toLowerCase() || 'shortest';
  const shipType = input.ship_type?.toString() || 'unknown';
  const cargoValue = Math.max(0, parseFloat(input.cargo_value) || 0);

  // Validation with detailed error messages
  const errors = [];
  const warnings = [];

  if (!origin || origin.length === 0) {
    errors.push('Origin system is required and cannot be empty');
  }
  if (!destination || destination.length === 0) {
    errors.push('Destination system is required and cannot be empty');
  }
  if (origin && destination && origin.toLowerCase() === destination.toLowerCase()) {
    errors.push('Origin and destination cannot be the same system');
  }

  // Route preference validation
  const validPreferences = ['shortest', 'secure', 'insecure'];
  let finalPreference = routePreference;
  if (!validPreferences.includes(routePreference)) {
    warnings.push(`Invalid route preference '${routePreference}', defaulting to 'shortest'`);
    finalPreference = 'shortest';
  }

  // Ship category determination with expanded logic
  function getShipCategory(ship) {
    if (!ship || ship === 'unknown') return 'unknown';
    const s = ship.toLowerCase();

    // Subcapital ships
    if (s.includes('frigate') || s.includes('destroyer') || s.includes('cruiser') || 
        s.includes('battlecruiser') || s.includes('battleship') || s.includes('interceptor') ||
        s.includes('assault') || s.includes('stealth bomber') || s.includes('recon')) {
      return 'subcapital';
    }

    // Industrial/Support
    if (s.includes('industrial') || s.includes('hauler') || s.includes('transport') ||
        s.includes('freighter') || s.includes('orca') || s.includes('bowhead')) {
      return 'industrial';
    }

    // Capital ships
    if (s.includes('capital') || s.includes('carrier') || s.includes('dreadnought') ||
        s.includes('titan') || s.includes('supercarrier') || s.includes('fax')) {
      return 'capital';
    }

    return 'unknown';
  }

  // Risk assessment with comprehensive logic
  const shipCategory = getShipCategory(shipType);
  const isHighValue = cargoValue > 1000000000; // 1B ISK
  const isExtremeValue = cargoValue > 10000000000; // 10B ISK

  let riskTolerance = 'high';
  if (isExtremeValue) riskTolerance = 'minimal';
  else if (isHighValue) riskTolerance = 'low';
  else if (cargoValue > 100000000) riskTolerance = 'medium'; // 100M ISK

  const riskProfile = {
    cargo_value: cargoValue,
    cargo_value_formatted: formatISK(cargoValue),
    risk_tolerance: riskTolerance,
    ship_category: shipCategory,
    requires_special_routing: isHighValue || shipCategory === 'capital',
    is_high_value_cargo: isHighValue,
    is_extreme_value_cargo: isExtremeValue,
    recommended_precautions: []
  };

  // Dynamic recommendations
  if (isExtremeValue) {
    riskProfile.recommended_precautions.push('EXTREME VALUE: Use multiple scouts, avoid peak hours, consider jump freighter');
  } else if (isHighValue) {
    riskProfile.recommended_precautions.push('HIGH VALUE: Use scout, avoid known gank systems, consider secure route');
  }

  if (shipCategory === 'capital') {
    riskProfile.recommended_precautions.push('CAPITAL: Plan jump routes, avoid highsec, coordinate with alliance');
  } else if (shipCategory === 'industrial') {
    riskProfile.recommended_precautions.push('INDUSTRIAL: Consider tank fitting, avoid autopilot in dangerous systems');
  }

  // Return validation errors if any
  if (errors.length > 0) {
    console.error('❌ Input validation failed:', errors.join(', '));
    return [{
      json: {
        success: false,
        validation_failed: true,
        error: 'Input validation failed',
        errors: errors,
        warnings: warnings,
        original_input: input
      }
    }];
  }

  console.log('✅ Input validation successful');
  if (warnings.length > 0) {
    console.warn('⚠️ Warnings:', warnings.join(', '));
  }
  console.log('📋 Risk Profile:', riskProfile);

  return [{
    json: {
      // Validated inputs
      origin: origin,
      destination: destination,
      route_preference: finalPreference,
      ship_type: shipType,
      cargo_value: cargoValue,

      // Analysis data
      risk_profile: riskProfile,

      // Metadata
      validation_success: true,
      warnings: warnings,
      processing_start: Date.now(),

      // Original input for reference
      original_input: input
    }
  }];

} catch (error) {
  console.error('❌ Validation error:', error.message);
  return [{
    json: {
      success: false,
      validation_failed: true,
      error: `Validation error: ${error.message}`,
      stack: error.stack,
      original_input: input
    }
  }];
}

// Replacement Code for "Redis Route Names"

const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

try {
    const input = $input.first().json;
    const routeIds = input.routeIds;
    const nameHash = 'eve:id_to_name';

    // Step 1: Get all names that are already in the cache
    const cachedNamesArray = routeIds.length > 0 ? await redis.hmget(nameHash, ...routeIds) : [];
    const nameMap = new Map(routeIds.map((id, i) => [id, cachedNamesArray[i]]));

    // Step 2: Find which IDs are missing
    const missingIds = routeIds.filter(id => !nameMap.get(id));

    // Step 3: Fetch ONLY the missing names from ESI
    if (missingIds.length > 0) {
        console.log(`Resolving ${missingIds.length} missing system names from ESI...`);
        try {
            const newNames = await this.helpers.httpRequest({
                url: 'https://esi.evetech.net/latest/universe/names/',
                method: 'POST',
                body: missingIds,
                json: true
            });

            // Step 4: Add new names to our map and cache them back to Redis
            const pipeline = redis.pipeline();
            newNames.forEach(item => {
                nameMap.set(item.id, item.name);
                pipeline.hset(nameHash, item.id, item.name);
            });
            await pipeline.exec();
        } catch(e) {
            console.warn(`Could not resolve some names from ESI: ${e.message}`);
        }
    }

    // Step 5: Build the final, ordered list of names
    const orderedNames = routeIds.map(id => nameMap.get(id) || `System ${id}`);

    return [{
        json: {
            ...input,
            routeNames: orderedNames,
            route_complete: true
        }
    }];

} catch (error) {
    console.error('Name resolution failed:', error.message);
    return [{ json: { ...$input.first().json, route_complete: false, error: error.message } }];
} finally {
    if (redis) await redis.quit();
}

// Structured route intelligence for programmatic consumption
const input = $input.first().json;

try {
  const staticAnalysis = input.static_analysis || {}; // Now correctly populated from Aggregate Route Intel
  const riskProfile = input.risk_profile || {};
  const liveIntelSummary = input.live_intel_summary || {}; // Now correctly populated from Aggregate Route Intel

  // Use the combined threat assessment calculated in the previous node
  const threatLevel = liveIntelSummary.threat_level || 'low';
  const threatScore = parseFloat((liveIntelSummary.threat_score || 0).toFixed(2)); // Format score for cleaner output
  const threatConfidence = liveIntelSummary.confidence || 'medium'; 

  // Combine recommendations and warnings from ALL relevant sources (input validator, and the aggregate intel node)
  const combinedRecommendations = Array.from(new Set([
    ...(riskProfile.recommended_precautions || []), // From Input Validator
    ...(staticAnalysis.recommendations || []),     // From Aggregate Route Intel (static-based)
    ...(liveIntelSummary.recommendations || [])    // From Aggregate Route Intel (live-based)
  ]));

  const combinedWarnings = Array.from(new Set([
    ...(staticAnalysis.warnings || []),           // From Aggregate Route Intel (static-based)
    ...(liveIntelSummary.warnings || [])          // From Aggregate Route Intel (live-based)
  ]));

  const report = {
    route: {
      origin: input.routeNames[0],
      destination: input.routeNames[input.routeNames.length - 1],
      total_jumps: input.total_jumps,
      system_ids: input.routeIds,
      system_names: input.routeNames
    },

    threat_assessment: {
      level: threatLevel,
      score: threatScore,
      confidence: threatConfidence
    },

    route_characteristics: {
      trade_hubs: staticAnalysis.trade_hubs_on_route || [], // Should now be populated correctly
      chokepoints: staticAnalysis.chokepoints_on_route || [],
      gank_hotspots: staticAnalysis.gank_hotspots_on_route || [],
      high_traffic_systems: staticAnalysis.high_traffic_on_route || [],
      security_breakdown: input.security_breakdown // Comes from System Enrichment
    },

    risk_factors: {
      cargo_value: riskProfile.cargo_value,
      cargo_value_formatted: riskProfile.cargo_value_formatted,
      ship_category: riskProfile.ship_category,
      requires_special_routing: riskProfile.requires_special_routing,
      is_high_value: riskProfile.is_high_value_cargo,
      is_extreme_value: riskProfile.is_extreme_value_cargo,
      risk_tolerance: riskProfile.risk_tolerance
    },

    systems: input.enriched_systems?.map(sys => ({
      id: sys.id,
      name: sys.name,
      index: sys.index,
      security_class: sys.security_class,
      security_status: sys.security,
      is_trade_hub: sys.static_analysis?.is_trade_hub || false,
      is_chokepoint: sys.static_analysis?.is_chokepoint || false,
      is_gank_hotspot: sys.static_analysis?.is_gank_hotspot || false,
      is_high_traffic: sys.static_analysis?.is_high_traffic || false,
      tags: sys.static_analysis?.tags || [],
      live_intel: sys.live_intel || { // Ensure live_intel always has default structure if not present
        kill_count: 0,
        total_value: 0,
        threat_level: 'low',
        last_activity: null,
        recent_kills_sample: []
      }
    })) || [],

    recommendations: combinedRecommendations.length > 0 ? combinedRecommendations : [], // Directly use combined and deduplicated
    warnings: combinedWarnings.length > 0 ? combinedWarnings : [], // Directly use combined and deduplicated

    live_intel_summary: liveIntelSummary,

    metadata: {
      generated_at: new Date().toISOString(),
      processing_time_ms: input.processing_start ? (Date.now() - input.processing_start) : null,
      data_sources: ['esi_api', 'static_analysis', 'live_intel_redis'],
      version: '1.0'
    }
  };

  return [{ json: report }];

} catch (error) {
  console.error('❌ Structured report generation failed:', error.message, error.stack);
  return [{ json: { error: error.message, stack: error.stack, input_data_for_debug: input } }];
}

// Enhanced system enrichment with batched Redis operations
const input = $input.first().json;
const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

try {
  const routeIds = input.routeIds;

  // Single pipeline for all Redis operations
  const pipeline = redis.pipeline();
  routeIds.forEach(id => {
    pipeline.hmget('eve:system_details', String(id));
    pipeline.hmget('eve:system_security', String(id));
    pipeline.hmget('eve:trade_hubs', String(id));
    pipeline.hmget('eve:chokepoints', String(id));
    pipeline.hmget('eve:gank_hotspots', String(id));
    pipeline.hmget('eve:high_traffic', String(id));
  });

  const results = await pipeline.exec();

  const enrichedSystems = routeIds.map((id, index) => {
    const baseIndex = index * 6;
    const details = results[baseIndex][1][0] ? JSON.parse(results[baseIndex][1][0]) : null;
    const security = results[baseIndex + 1][1][0] ? JSON.parse(results[baseIndex + 1][1][0]) : null;

    // Static analysis flags
    const isTradeHub = results[baseIndex + 2][1][0] === 'true';
    const isChokepoint = results[baseIndex + 3][1][0] === 'true';
    const isGankHotspot = results[baseIndex + 4][1][0] === 'true';
    const isHighTraffic = results[baseIndex + 5][1][0] === 'true';

    const tags = [];
    if (isTradeHub) tags.push('trade_hub');
    if (isChokepoint) tags.push('chokepoint');
    if (isGankHotspot) tags.push('gank_hotspot');
    if (isHighTraffic) tags.push('high_traffic');

    return {
      id,
      name: input.routeNames[index],
      index,
      security: details?.security || null,
      security_class: security?.class || 'unknown',
      region_id: details?.regionID || null,
      constellation_id: details?.constellationID || null,
      static_analysis: {
        is_trade_hub: isTradeHub,
        is_chokepoint: isChokepoint,
        is_gank_hotspot: isGankHotspot,
        is_high_traffic: isHighTraffic,
        tags: tags
      }
    };
  });

  const securityBreakdown = {
    highsec: enrichedSystems.filter(s => s.security_class === 'highsec').length,
    lowsec: enrichedSystems.filter(s => s.security_class === 'lowsec').length, 
    nullsec: enrichedSystems.filter(s => s.security_class === 'nullsec').length,
    wormhole: enrichedSystems.filter(s => s.security_class === 'wormhole').length,
    unknown: enrichedSystems.filter(s => s.security_class === 'unknown').length
  };

  return [{ json: { ...input, enriched_systems: enrichedSystems, security_breakdown: securityBreakdown } }];

} catch (error) {
  console.error('System enrichment failed:', error.message);
  return [{ json: { ...input, enrichment_failed: true } }];
} finally {
  if (redis) await redis.quit();
}

// Enhanced route data combiner - fixed node references
const input = $input.all();
const originalData = $('Input Validator').first().json;

// Find the systems data from Get System IDs node
const systemsData = input.find(item => item.json.systems)?.json;

// Extract route IDs from numeric items (route data from Calculate Route)
const routeIds = input.filter(item => typeof item.json === 'number').map(item => item.json);

try {
  // Enhanced metadata
  const enhancedMetadata = {
    calculation_method: 'esi_api',
    origin_id: systemsData?.systems[0]?.id,
    destination_id: systemsData?.systems[1]?.id,
    cached: false,
    api_sources: ['esi']
  };

  console.log(`✅ Route data combined: ${routeIds.length} jumps`);

  return [{
    json: {
      ...originalData,
      routeIds: routeIds,
      routeNames: systemsData?.systems?.map(s => s.name) || [],
      total_jumps: routeIds.length,
      route_planning_success: routeIds.length > 0,
      route_metadata: enhancedMetadata
    }
  }];

} catch (error) {
  console.error('❌ Enhanced route combination failed:', error.message);
  return [{
    json: {
      ...originalData,
      routeIds: routeIds,
      routeNames: systemsData?.systems?.map(s => s.name) || [],
      total_jumps: routeIds.length,
      route_planning_success: routeIds.length > 0,
      intel_processing_failed: true,
      error: error.message
    }
  }];
}

const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 10000 });

try {
    const input = $input.first().json;
    const routeIds = input.routeIds || [];

    if (routeIds.length === 0) {
        console.warn('No route IDs to fetch intel for.');
        return [{ json: { ...input, live_intel_raw_data: [], redis_fetch_success: true } }];
    }

    console.log(`📡 Fetching live intel for ${routeIds.length} systems...`);

    const pipeline = redis.pipeline();
    const now = Math.floor(Date.now() / 1000); // Convert to seconds
    const twentyFourHoursAgo = now - (24 * 60 * 60); // 24 hours in seconds

    routeIds.forEach(id => {
        pipeline.hgetall(`intel:stats:system:${id}`);
        pipeline.zrevrangebyscore(
            `intel:kills:system:${id}`, 
            '+inf', 
            twentyFourHoursAgo, 
            'LIMIT', 0, 50
        );
    });
    const results = await pipeline.exec();

    const liveIntelData = [];
    for (let i = 0; i < routeIds.length; i++) {
        const statsResult = results[i * 2];
        const killIdsResult = results[i * 2 + 1];

        const stats = (statsResult && statsResult[1] && Object.keys(statsResult[1]).length > 0) ? statsResult[1] : null;
        const killIds = (killIdsResult && killIdsResult[1]) ? killIdsResult[1] : [];

        // Now fetch the actual kill data using the IDs
        const recentKills = [];
        if (killIds.length > 0) {
            const killDataPipeline = redis.pipeline();
            killIds.forEach(killId => {
                killDataPipeline.hget('intel:kill:data', String(killId));
            });
            const killDataResults = await killDataPipeline.exec();

            for (const result of killDataResults) {
                if (result && result[1]) {
                    try {
                        const killData = JSON.parse(result[1]);
                        recentKills.push({
                            id: killData.killmail_id,
                            time: killData.killmail_time,
                            val: killData.total_value || 0,
                            v_ship: killData.victim?.ship_type_name || 'Unknown Ship',
                            k_char: killData.attackers?.[0]?.character_name || 'Unknown'
                        });
                    } catch (e) {
                        console.warn(`Failed to parse kill data:`, e.message);
                    }
                }
            }
        }

        liveIntelData.push({
            system_id: routeIds[i],
            stats: stats,
            recent_kills: recentKills
        });
    }

    console.log(`✅ Successfully fetched live intel for ${liveIntelData.filter(d => d.recent_kills.length > 0).length} systems.`);

    return [{ 
        json: { 
            ...input, 
            live_intel_raw_data: liveIntelData,
            redis_fetch_success: true
        } 
    }];

} catch (error) {
    console.error('❌ Error fetching live intel from Redis:', error.message);
    return [{ 
        json: { 
            ...input, 
            live_intel_raw_data: [],
            redis_fetch_success: false,
            redis_error: error.message
        } 
    }];
} finally {
    if (redis) await redis.quit();
}

const input = $input.first().json;

console.log('--- START PER-SYSTEM LIVE INTEL PROCESSING (ROBUST) ---');

const enrichedSystems = input.enriched_systems || [];
const liveIntelData = input.live_intel_raw_data || [];

let totalKills = 0, totalValue = 0, systemsWithActivity = 0, highValueKills = 0;
const hunterOrgs = new Map();
const victimShips = new Map();
const recentActivity = [];
const processedKills = new Set();
const now = new Date();
const oneHourAgo = new Date(now.getTime() - (60 * 60 * 1000));
const twentyFourHoursAgo = new Date(now.getTime() - (24 * 60 * 60 * 1000));

const processedEnrichedSystems = enrichedSystems.map((system, i) => {
    const intelForSystem = liveIntelData.find(d => d.system_id === system.id);

    system.static_analysis = system.static_analysis || {};

    const recentKills = intelForSystem?.recent_kills || [];

    // Filter kills by time
    const kills_1h = recentKills.filter(k => new Date(k.time) >= oneHourAgo);
    const kills_24h = recentKills.filter(k => new Date(k.time) >= twentyFourHoursAgo);

    // Calculate values for the 1-hour and 24-hour windows
    const kill_count_1h = kills_1h.length;
    const kill_count_24h = kills_24h.length;
    const total_value_1h = kills_1h.reduce((sum, k) => sum + (k.val || 0), 0);
    const total_value_24h = kills_24h.reduce((sum, k) => sum + (k.val || 0), 0);

    // Aggregate route-wide totals from the 24h window
    if (kill_count_24h > 0) {
        systemsWithActivity++;
        totalKills += kill_count_24h;
        totalValue += total_value_24h;

        // Populate recent activity for the route report (using the full recent list)
        for (const kill of recentKills) {
            const killKey = `${kill.id}-${kill.time}-${system.name}`;
            if (processedKills.has(killKey)) continue;
            processedKills.add(killKey);

            if (kill.val > 1000000000) highValueKills++;
            if (kill.k_char && kill.k_char !== 'Unknown') hunterOrgs.set(kill.k_char, (hunterOrgs.get(kill.k_char) || 0) + 1);
            if (kill.v_ship && kill.v_ship !== 'Unknown Ship') victimShips.set(kill.v_ship, (victimShips.get(kill.v_ship) || 0) + 1);
            recentActivity.push({ 
                system_name: system.name, 
                victim_ship: kill.v_ship, 
                killer: kill.k_char, 
                value: kill.val, 
                time: kill.time 
            });
        }
    }

    let systemThreat = 'low';
    if (kill_count_24h > 30 || system.static_analysis.is_gank_hotspot) systemThreat = 'extreme';
    else if (kill_count_24h > 15 || system.static_analysis.is_chokepoint) systemThreat = 'high';
    else if (kill_count_24h > 5 || system.static_analysis.is_high_traffic) systemThreat = 'medium';

    system.live_intel = {
        kill_count: kill_count_24h,
        total_value: total_value_24h,
        threat_level: systemThreat,
        last_activity: intelForSystem?.stats?.last_activity || null,
        // The entire list of recent kills is now being passed
        recent_kills_sample: recentKills.filter((kill, index, arr) => 
            arr.findIndex(k => k.id === kill.id && k.time === kill.time) === index
        )
    };

    return system;
});

return [{
    json: {
        ...input,
        enriched_systems: processedEnrichedSystems,
        totalKills_aggregated: totalKills,
        totalValue_aggregated: totalValue,
        systemsWithActivity_aggregated: systemsWithActivity,
        highValueKills_aggregated: highValueKills,
        hunterOrgs_map: Object.fromEntries(hunterOrgs),
        victimShips_map: Object.fromEntries(victimShips),
        recentActivity_list: recentActivity
    }
}];

const input = $input.first().json;

console.log('--- START AGGREGATE ROUTE INTEL ---');

const enrichedSystems = input.enriched_systems || [];
const riskProfile = input.risk_profile || {};
const routeIds = input.routeIds || [];

// These are now correctly aggregated from the 24-hour window in the previous node
const totalKills = input.totalKills_aggregated || 0;
const totalValue = input.totalValue_aggregated || 0;
const systemsWithActivity = input.systemsWithActivity_aggregated || 0;
const highValueKills = input.highValueKills_aggregated || 0;
const hunterOrgs_map = input.hunterOrgs_map || {};
const victimShips_map = input.victimShips_map || {};
const recentActivity_list = input.recentActivity_list || [];

const analysis = {
 trade_hubs_on_route: enrichedSystems.filter(s => s.static_analysis?.is_trade_hub).map(s => s.name),
 chokepoints_on_route: enrichedSystems.filter(s => s.static_analysis?.is_chokepoint).map(s => s.name),
 gank_hotspots_on_route: enrichedSystems.filter(s => s.static_analysis?.is_gank_hotspot).map(s => s.name),
 high_traffic_on_route: enrichedSystems.filter(s => s.static_analysis?.is_high_traffic).map(s => s.name),
 warnings: [],
 recommendations: []
};

// Rebalanced threat scoring
let threatScore = 0;
threatScore += totalKills * 0.5;
threatScore += systemsWithActivity * 5;
threatScore += highValueKills * 10;
threatScore += Math.log10(totalValue + 1) * 2;

// Reduced multipliers for more realistic scoring
threatScore += analysis.gank_hotspots_on_route.length * 20;
threatScore += analysis.chokepoints_on_route.length * 10;
threatScore += analysis.high_traffic_on_route.length * 2;
threatScore += analysis.trade_hubs_on_route.length * 1;

if (riskProfile.is_high_value_cargo) threatScore += 50;
if (riskProfile.ship_category === 'industrial') threatScore += 25;
if (riskProfile.ship_category === 'capital') threatScore += 30;

const threatLevel = threatScore > 100 ? 'extreme' :
                  threatScore > 60 ? 'high' :
                  threatScore > 30 ? 'medium' : 'low';

if (analysis.gank_hotspots_on_route.length > 0) {
 analysis.warnings.push(`DANGER: Route passes through gank hotspot(s): ${analysis.gank_hotspots_on_route.join(', ')}`);
}
if (totalKills > 50) {
 analysis.warnings.push(`HIGH ACTIVITY: ${totalKills} kills detected across route`);
}
if (highValueKills > 5) {
 analysis.warnings.push(`HIGH VALUE TARGETS: ${highValueKills} billion+ ISK kills detected`);
}
if (analysis.chokepoints_on_route.length > 0) {
 analysis.warnings.push(`Route passes through chokepoint(s): ${analysis.chokepoints_on_route.join(', ')}`);
}

if (riskProfile.is_high_value_cargo && analysis.gank_hotspots_on_route.length > 0) {
