}
if (riskProfile.ship_category === 'industrial' && analysis.chokepoints_on_route.length > 0) {
 analysis.recommendations.push('INDUSTRIAL + CHOKEPOINT: Fit for tank, avoid autopilot');
}
if (riskProfile.ship_category === 'capital') {
