// Get System IDs - Redis-first with ESI fallback
const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

try {
    const input = $input.first().json;
    const origin = input.origin;
    const destination = input.destination;

    console.log(`Resolving system names: ${origin} -> ${destination}`);

    // Try Redis cache first for both systems
    const [originId, destinationId] = await Promise.all([
        redis.hget('eve:solar_system_name_to_id', origin.toLowerCase()),
        redis.hget('eve:solar_system_name_to_id', destination.toLowerCase())
    ]);

    const systems = [];
    const systemsToResolve = [];

    // Check what we need to resolve via ESI
    if (originId) {
        systems.push({ id: parseInt(originId), name: origin });
    } else {
        systemsToResolve.push(origin);
    }

    if (destinationId) {
        systems.push({ id: parseInt(destinationId), name: destination });
    } else {
        systemsToResolve.push(destination);
    }

    // ESI fallback for missing systems
    if (systemsToResolve.length > 0) {
        console.log(`Resolving ${systemsToResolve.length} systems via ESI...`);

        const esiResponse = await this.helpers.httpRequest({
            url: 'https://esi.evetech.net/latest/universe/ids/',
            method: 'POST',
            body: systemsToResolve,
            json: true,
            headers: { 
                'User-Agent': 'n8n-eve-route-planner/1.0',
                'Content-Type': 'application/json'
            }
        });

        if (esiResponse.solar_systems) {
            // Cache the results and add to systems array
            const pipeline = redis.pipeline();

            for (const system of esiResponse.solar_systems) {
                systems.push({ id: system.id, name: system.name });
                pipeline.hset('eve:solar_system_name_to_id', system.name.toLowerCase(), system.id.toString());
                pipeline.hset('eve:id_to_name', system.id.toString(), system.name);
            }

            await pipeline.exec();
            console.log(`Cached ${esiResponse.solar_systems.length} new systems`);
        }
    }

    // Ensure we have both systems
    if (systems.length < 2) {
        const missingSystem = systems.length === 0 ? `${origin} and ${destination}` : 
                             !originId ? origin : destination;
        throw new Error(`Could not resolve system(s): ${missingSystem}`);
    }

    // Order systems correctly (origin first, destination second)
    const orderedSystems = [
        systems.find(s => s.name.toLowerCase() === origin.toLowerCase()),
        systems.find(s => s.name.toLowerCase() === destination.toLowerCase())
    ];

    console.log(`✅ Resolved systems: ${orderedSystems[0].name} (${orderedSystems[0].id}) -> ${orderedSystems[1].name} (${orderedSystems[1].id})`);

    return [{ json: { ...input, systems: orderedSystems } }];

} catch (error) {
    console.error('❌ System ID resolution failed:', error.message);
    return [{ json: { ...input, error: error.message, systems: [] } }];
} finally {
    if (redis && redis.status === 'ready') {
        await redis.quit();
    }
}
